"""Additive migration; existing users, calculations and balances are preserved."""
STATEMENTS = (
    "CREATE TABLE products (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT GENERATED ALWAYS AS ('MOD-' || printf('%04d',id)) STORED UNIQUE, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', category TEXT NOT NULL CHECK(category IN ('decorative','functional','mixed')), printer_id INTEGER REFERENCES printers(id), filament_id INTEGER REFERENCES filaments(id), settings TEXT NOT NULL DEFAULT '', estimated_minutes INTEGER NOT NULL DEFAULT 0 CHECK(estimated_minutes>=0), planned_cost_cents INTEGER CHECK(planned_cost_cents>=0), suggested_price_cents INTEGER CHECK(suggested_price_cents>=0), quality_notes TEXT NOT NULL DEFAULT '', archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0,1)))",
    "CREATE TABLE variants (id INTEGER PRIMARY KEY AUTOINCREMENT, product_id INTEGER NOT NULL REFERENCES products(id), name TEXT NOT NULL, size TEXT NOT NULL DEFAULT '', color TEXT NOT NULL DEFAULT '', material TEXT NOT NULL DEFAULT '', planned_cost_cents INTEGER CHECK(planned_cost_cents>=0), suggested_price_cents INTEGER CHECK(suggested_price_cents>=0), calculation_id INTEGER REFERENCES calculations(id), cost_snapshot TEXT, archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0,1)), UNIQUE(product_id,name))",
    "CREATE TABLE product_photos (id INTEGER PRIMARY KEY AUTOINCREMENT, product_id INTEGER NOT NULL REFERENCES products(id), path TEXT NOT NULL UNIQUE, original_name TEXT NOT NULL, sha256 TEXT NOT NULL, created_at TEXT NOT NULL, is_primary INTEGER NOT NULL DEFAULT 0 CHECK(is_primary IN (0,1)))",
    "CREATE UNIQUE INDEX one_primary_photo ON product_photos(product_id) WHERE is_primary=1",
    "CREATE TABLE project_versions (id INTEGER PRIMARY KEY AUTOINCREMENT, product_id INTEGER NOT NULL REFERENCES products(id), version INTEGER NOT NULL, path TEXT NOT NULL UNIQUE, original_name TEXT NOT NULL, sha256 TEXT NOT NULL, created_at TEXT NOT NULL, notes TEXT NOT NULL, is_preferred INTEGER NOT NULL DEFAULT 0 CHECK(is_preferred IN (0,1)), UNIQUE(product_id,version))",
    "CREATE UNIQUE INDEX one_preferred_project ON project_versions(product_id) WHERE is_preferred=1",
    "CREATE TABLE materials (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, unit TEXT NOT NULL, balance_milli INTEGER NOT NULL CHECK(balance_milli>=0), reference_per_unit TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0,1)))",
    "CREATE TABLE receipts (id INTEGER PRIMARY KEY AUTOINCREMENT, variant_id INTEGER NOT NULL REFERENCES variants(id), created_at TEXT NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>0), total_cost_cents INTEGER NOT NULL CHECK(total_cost_cents>=0), source TEXT NOT NULL, calculation_id INTEGER UNIQUE REFERENCES calculations(id), cost_basis TEXT NOT NULL, cost_snapshot TEXT, operation_key TEXT NOT NULL UNIQUE)",
    "CREATE TABLE reservations (id INTEGER PRIMARY KEY AUTOINCREMENT, variant_id INTEGER NOT NULL REFERENCES variants(id), reference TEXT NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>0), created_at TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('reserved','released','issued')), operation_key TEXT NOT NULL UNIQUE)",
    "CREATE TABLE pieces (id INTEGER PRIMARY KEY AUTOINCREMENT, receipt_id INTEGER NOT NULL REFERENCES receipts(id), variant_id INTEGER NOT NULL REFERENCES variants(id), state TEXT NOT NULL CHECK(state IN ('available','reserved','personal','quarantine','discarded','issued')), condition TEXT NOT NULL, unit_cost_cents INTEGER NOT NULL CHECK(unit_cost_cents>=0), reservation_id INTEGER REFERENCES reservations(id), CHECK((state='reserved' AND reservation_id IS NOT NULL) OR (state!='reserved' AND reservation_id IS NULL)))",
    "CREATE TABLE piece_reviews (id INTEGER PRIMARY KEY AUTOINCREMENT, piece_id INTEGER NOT NULL REFERENCES pieces(id), created_at TEXT NOT NULL, reviewer TEXT NOT NULL, condition TEXT NOT NULL, result TEXT NOT NULL CHECK(result IN ('approved','rejected')))",
    "CREATE TABLE losses (id INTEGER PRIMARY KEY AUTOINCREMENT, entity_kind TEXT NOT NULL CHECK(entity_kind IN ('piece','filament','material')), unit TEXT NOT NULL, created_at TEXT NOT NULL, occurred_on TEXT NOT NULL, reason TEXT NOT NULL, notes TEXT NOT NULL, quantity_milli INTEGER NOT NULL CHECK(quantity_milli>0), cost_cents INTEGER NOT NULL CHECK(cost_cents>=0), cost_basis TEXT NOT NULL, operation_key TEXT NOT NULL UNIQUE)",
    "CREATE TABLE loss_pieces (loss_id INTEGER NOT NULL REFERENCES losses(id), piece_id INTEGER NOT NULL UNIQUE REFERENCES pieces(id), PRIMARY KEY(loss_id,piece_id))",
    "CREATE TABLE stock_movements (id INTEGER PRIMARY KEY AUTOINCREMENT, created_at TEXT NOT NULL, kind TEXT NOT NULL, filament_id INTEGER REFERENCES filaments(id), material_id INTEGER REFERENCES materials(id), piece_id INTEGER REFERENCES pieces(id), quantity_milli INTEGER, previous TEXT NOT NULL, current TEXT NOT NULL, reason TEXT NOT NULL, operation_key TEXT NOT NULL UNIQUE, cost_cents INTEGER CHECK(cost_cents>=0), CHECK((filament_id IS NOT NULL)+(material_id IS NOT NULL)+(piece_id IS NOT NULL)=1))",
    "INSERT INTO stock_movements(created_at,kind,filament_id,quantity_milli,previous,current,reason,operation_key) SELECT strftime('%Y-%m-%dT%H:%M:%SZ','now'),'opening',id,remaining_mg,'null',COALESCE(CAST(remaining_mg AS TEXT),'null'),'Saldo preservado na migração da Fase 2','phase3-opening-filament-'||id FROM filaments",
)
